CREATE OR REPLACE VIEW v_active_fee_schedule (schedule_id, schedule_code, schedule_name, effective_date, termination_date, effective_end_date, status, detail_count, average_allowed_amount) AS SELECT fs.schedule_id, fs.schedule_code, fs.schedule_name,
       fs.effective_date, fs.termination_date,
       coalesce(fs.termination_date, timestamp(0) '2999-12-31') effective_end_date,
       fs.status, COUNT(fsd.schedule_detail_id) detail_count,
       coalesce(AVG(fsd.allowed_amount),0) average_allowed_amount
FROM fee_schedule fs
LEFT JOIN fee_schedule_detail fsd ON fsd.schedule_id=fs.schedule_id
WHERE fs.status='ACTIVE'
GROUP BY fs.schedule_id,fs.schedule_code,fs.schedule_name,
         fs.effective_date,fs.termination_date,fs.status;

