CREATE OR REPLACE VIEW v_claim_summary (claim_id, claim_number, member_number, provider_code, provider_name, service_date, claim_status, status_description, total_billed, total_allowed, adjustment_amount) AS SELECT c.claim_id,c.claim_number,m.member_number,p.provider_code,
       p.provider_name,c.service_date,c.claim_status,
       CASE WHEN c.claim_status='NEW' THEN 'Pending Intake' WHEN c.claim_status='PROCESSING' THEN 'Under Review' WHEN c.claim_status='PAID' THEN 'Completed' WHEN c.claim_status='DENIED' THEN 'Rejected'  ELSE 'Unknown' END  status_description,
       coalesce(c.total_billed,0) total_billed,
       coalesce(c.total_allowed,0) total_allowed,
       coalesce(c.total_billed,0)-coalesce(c.total_allowed,0) adjustment_amount
FROM claim c JOIN member m ON m.member_id=c.member_id
JOIN provider p ON p.provider_id=c.provider_id;

